namespace ShipmentTracker.Client.Models;

public enum ShipmentStatus
{
    Pending,
    PickedUp,
    InTransit,
    OutForDelivery,
    Delivered,
    Delayed
}

public class Shipment
{
    public int Id { get; set; }
    public string TrackingNumber { get; set; } = string.Empty;
    public string Origin { get; set; } = string.Empty;
    public string Destination { get; set; } = string.Empty;
    public ShipmentStatus Status { get; set; }
    public DateTime ShippedDate { get; set; }
    public DateTime EstimatedDelivery { get; set; }
    public string RecipientName { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

using ShipmentTracker.Client.Models;

namespace ShipmentTracker.Client.Services;

public interface IShipmentService
{
    Task<List<Shipment>> GetShipmentsAsync();
    Task<Shipment?> GetShipmentByTrackingNumberAsync(string trackingNumber);
    Task UpdateStatusAsync(int id, ShipmentStatus newStatus);
}

using System.Net.Http.Json;
using ShipmentTracker.Client.Models;

namespace ShipmentTracker.Client.Services;

public class ClientShipmentService(HttpClient http) : IShipmentService
{
    public async Task<List<Shipment>> GetShipmentsAsync()
    {
        return await http.GetFromJsonAsync<List<Shipment>>("api/shipments") ?? [];
    }

    public async Task<Shipment?> GetShipmentByTrackingNumberAsync(string trackingNumber)
    {
        var response = await http.GetAsync($"api/shipments/track/{Uri.EscapeDataString(trackingNumber)}");
        if (!response.IsSuccessStatusCode)
            return null;
        return await response.Content.ReadFromJsonAsync<Shipment>();
    }

    public async Task UpdateStatusAsync(int id, ShipmentStatus newStatus)
    {
        await http.PutAsync($"api/shipments/{id}/status?newStatus={newStatus}", null);
    }
}

using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;

namespace ShipmentTracker.Services;

public class ServerShipmentService : IShipmentService
{
    private static readonly List<Shipment> Shipments =
    [
        new()
        {
            Id = 1, TrackingNumber = "TRK-1001", Origin = "New York, US",
            Destination = "London, UK", Status = ShipmentStatus.InTransit,
            ShippedDate = DateTime.UtcNow.AddDays(-3),
            EstimatedDelivery = DateTime.UtcNow.AddDays(4),
            RecipientName = "Alice Johnson", Description = "Electronics – 2 boxes"
        },
        new()
        {
            Id = 2, TrackingNumber = "TRK-1002", Origin = "Shanghai, CN",
            Destination = "Los Angeles, US", Status = ShipmentStatus.Pending,
            ShippedDate = DateTime.UtcNow.AddDays(-1),
            EstimatedDelivery = DateTime.UtcNow.AddDays(10),
            RecipientName = "Bob Smith", Description = "Furniture – 1 pallet"
        },
        new()
        {
            Id = 3, TrackingNumber = "TRK-1003", Origin = "Berlin, DE",
            Destination = "Tokyo, JP", Status = ShipmentStatus.OutForDelivery,
            ShippedDate = DateTime.UtcNow.AddDays(-7),
            EstimatedDelivery = DateTime.UtcNow,
            RecipientName = "Yuki Tanaka", Description = "Auto parts – 5 crates"
        },
        new()
        {
            Id = 4, TrackingNumber = "TRK-1004", Origin = "São Paulo, BR",
            Destination = "Miami, US", Status = ShipmentStatus.Delivered,
            ShippedDate = DateTime.UtcNow.AddDays(-10),
            EstimatedDelivery = DateTime.UtcNow.AddDays(-2),
            RecipientName = "Carlos Rivera", Description = "Coffee beans – 50 kg"
        },
        new()
        {
            Id = 5, TrackingNumber = "TRK-1005", Origin = "Sydney, AU",
            Destination = "Vancouver, CA", Status = ShipmentStatus.Delayed,
            ShippedDate = DateTime.UtcNow.AddDays(-5),
            EstimatedDelivery = DateTime.UtcNow.AddDays(3),
            RecipientName = "Emma Wilson", Description = "Medical supplies – 3 boxes"
        }
    ];

    private static readonly Lock SyncLock = new();

    public Task<List<Shipment>> GetShipmentsAsync()
    {
        lock (SyncLock)
        {
            return Task.FromResult(Shipments.Select(s => Clone(s)).ToList());
        }
    }

    public Task<Shipment?> GetShipmentByTrackingNumberAsync(string trackingNumber)
    {
        lock (SyncLock)
        {
            var shipment = Shipments.FirstOrDefault(
                s => s.TrackingNumber.Equals(trackingNumber, StringComparison.OrdinalIgnoreCase));
            return Task.FromResult(shipment is null ? null : Clone(shipment));
        }
    }

    public Task UpdateStatusAsync(int id, ShipmentStatus newStatus)
    {
        lock (SyncLock)
        {
            var shipment = Shipments.FirstOrDefault(s => s.Id == id);
            if (shipment is not null)
                shipment.Status = newStatus;
        }
        return Task.CompletedTask;
    }

    private static Shipment Clone(Shipment s) => new()
    {
        Id = s.Id,
        TrackingNumber = s.TrackingNumber,
        Origin = s.Origin,
        Destination = s.Destination,
        Status = s.Status,
        ShippedDate = s.ShippedDate,
        EstimatedDelivery = s.EstimatedDelivery,
        RecipientName = s.RecipientName,
        Description = s.Description
    };
}

