@attribute [Microsoft.AspNetCore.Authorization.Authorize]
@inject IShipmentService ShipmentService

<PageTitle>Shipments – Dispatcher</PageTitle>

<h2>📋 Shipment Dashboard</h2>

<div class="row mb-3 g-2">
    <div class="col-auto">
        <input type="text" class="form-control" placeholder="Search destination…"
               @bind="searchText" @bind:event="oninput" />
    </div>
    <div class="col-auto">
        <select class="form-select" @bind="statusFilter">
            <option value="">All Statuses</option>
            @foreach (var status in Enum.GetValues<ShipmentStatus>())
            {
                <option value="@status">@status</option>
            }
        </select>
    </div>
    <div class="col-auto">
        <button class="btn btn-secondary" @onclick="RefreshAsync">↻ Refresh</button>
    </div>
</div>

@if (shipments is null)
{
    <p><em>Loading shipments…</em></p>
}
else if (!FilteredShipments.Any())
{
    <div class="alert alert-info">No shipments match your filters.</div>
}
else
{
    <div class="table-responsive">
        <table class="table table-striped table-hover align-middle">
            <thead class="table-dark">
                <tr>
                    <th>Tracking #</th>
                    <th>Origin</th>
                    <th>Destination</th>
                    <th>Recipient</th>
                    <th>Status</th>
                    <th>Est. Delivery</th>
                    <th>Action</th>
                </tr>
            </thead>
            <tbody>
                @foreach (var s in FilteredShipments)
                {
                    <tr>
                        <td><strong>@s.TrackingNumber</strong></td>
                        <td>@s.Origin</td>
                        <td>@s.Destination</td>
                        <td>@s.RecipientName</td>
                        <td><span class="badge @GetStatusBadge(s.Status)">@s.Status</span></td>
                        <td>@s.EstimatedDelivery.ToString("MMM dd, yyyy")</td>
                        <td>
                            <select class="form-select form-select-sm"
                                    value="@s.Status"
                                    @onchange="e => OnStatusChanged(s, e)">
                                @foreach (var status in Enum.GetValues<ShipmentStatus>())
                                {
                                    <option value="@status">@status</option>
                                }
                            </select>
                        </td>
                    </tr>
                }
            </tbody>
        </table>
    </div>
}

@code {
    private List<Shipment>? shipments;
    private string searchText = "";
    private string statusFilter = "";

    private IEnumerable<Shipment> FilteredShipments =>
        (shipments ?? [])
            .Where(s => string.IsNullOrEmpty(searchText)
                || s.Destination.Contains(searchText, StringComparison.OrdinalIgnoreCase))
            .Where(s => string.IsNullOrEmpty(statusFilter)
                || s.Status.ToString() == statusFilter);

    protected override async Task OnInitializedAsync()
    {
        shipments = await ShipmentService.GetShipmentsAsync();
    }

    private async Task RefreshAsync()
    {
        shipments = null;
        shipments = await ShipmentService.GetShipmentsAsync();
    }

    private async Task OnStatusChanged(Shipment shipment, ChangeEventArgs e)
    {
        if (Enum.TryParse<ShipmentStatus>(e.Value?.ToString(), out var newStatus))
        {
            await ShipmentService.UpdateStatusAsync(shipment.Id, newStatus);
            shipment.Status = newStatus;
        }
    }

    private static string GetStatusBadge(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Delayed => "bg-danger",
        _ => "bg-secondary"
    };
}

@page "/track"
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@inject IShipmentService ShipmentService

<PageTitle>Track Shipment</PageTitle>

<h2>🔍 Track Your Shipment</h2>

<div class="row mb-4">
    <div class="col-md-6">
        <div class="input-group">
            <input type="text" class="form-control" placeholder="Enter tracking number (e.g. TRK-1001)"
                   @bind="trackingNumber" @bind:event="oninput"
                   @onkeydown="OnKeyDown" />
            <button class="btn btn-primary" @onclick="TrackAsync" disabled="@isLoading">
                @(isLoading ? "Searching…" : "Track")
            </button>
        </div>
    </div>
</div>

@if (searched && result is null)
{
    <div class="alert alert-warning">
        No shipment found for tracking number <strong>@searchedNumber</strong>. Please check the number and try again.
    </div>
}

@if (result is not null)
{
    <div class="card shadow-sm">
        <div class="card-header bg-dark text-white">
            <h4 class="mb-0">Shipment @result.TrackingNumber</h4>
        </div>
        <div class="card-body">
            <div class="row g-3">
                <div class="col-md-6">
                    <dl>
                        <dt>Status</dt>
                        <dd><span class="badge fs-6 @GetStatusBadge(result.Status)">@result.Status</span></dd>
                        <dt>Description</dt>
                        <dd>@result.Description</dd>
                        <dt>Recipient</dt>
                        <dd>@result.RecipientName</dd>
                    </dl>
                </div>
                <div class="col-md-6">
                    <dl>
                        <dt>Origin</dt>
                        <dd>@result.Origin</dd>
                        <dt>Destination</dt>
                        <dd>@result.Destination</dd>
                        <dt>Shipped Date</dt>
                        <dd>@result.ShippedDate.ToString("MMM dd, yyyy")</dd>
                        <dt>Estimated Delivery</dt>
                        <dd class="fw-bold text-primary">@result.EstimatedDelivery.ToString("MMM dd, yyyy")</dd>
                    </dl>
                </div>
            </div>

            @{
                var progress = GetProgress(result);
            }
            <div class="mt-3">
                <label class="form-label fw-bold">Delivery Progress</label>
                <div class="progress" style="height: 25px;">
                    <div class="progress-bar @GetProgressColor(result.Status)"
                         role="progressbar" style="width: @progress%"
                         aria-valuenow="@progress" aria-valuemin="0" aria-valuemax="100">
                        @progress%
                    </div>
                </div>
            </div>
        </div>
    </div>
}

